const context = $('Get Query Context').item.json;
const intent = $('Query Webhook').item.json.body.intent;
const rows = Array.isArray($json) ? $json : ($json.routes ?? $json.trips ?? [$json]);
if (!rows.length || !rows[0] || rows[0].available === false) return [{ json: { phone_number: context.phone_number, text: 'Não encontrei viagens com esses dados. Informe origem, destino e data para eu tentar novamente.' } }];
const lines = rows.slice(0, 5).map((r) => { const price = r.price ?? (r.price_cents != null ? 'R$ ' + (r.price_cents / 100).toFixed(2).replace('.', ',') : 'consulte'); return '• ' + (r.origin ?? context.state_payload.origin ?? '') + ' → ' + (r.destination ?? context.state_payload.destination ?? '') + ' | ' + (r.departure_time ?? r.time ?? 'horário a confirmar') + ' | ' + price; });
const title = intent === 'ASK_PRICES' ? 'Valores encontrados:' : 'Horários encontrados:';
return [{ json: { phone_number: context.phone_number, text: title + '\n' + lines.join('\n') } }];

const req = $('Payment Creation Webhook').first().json.body;
const user = $json || {};

const cpf = req.passenger_cpf || req.documents?.["1"] || user.cpf || "00000000000";
const name = req.passenger_name || req.name || req.customers?.["1"] || user.full_name || "Passageiro";
const phone = user.phone_number || req.phone || "5593999999999";
const price = Number(req.price || 0);
const tax = String(req.tax ?? "0.0");
const seatNumber = req.seat_number || (Array.isArray(req.seat_numbers) ? req.seat_numbers[0] : null);

const dataArray = [{
  comodity: "Assento",
  field: "speed_boat_price",
  customer_fields: 1,
  min_customer_fields: 1,
  price: price,
  tax: tax,
  quantity: 1
}];

const order = {
  route_id: parseInt(req.route_id),
  trip_id: parseInt(req.trip_id),
  date: req.date,
  payment_method: req.payment_method || "PIX",
  name: name,
  phone: phone,
  customers: { "1": name },
  documents: { "1": String(cpf).replace(/\D/g, "") },
  document_types: { "1": "cpf" },
  birthdays: [req.passenger_birthday || (Array.isArray(req.birthdays) ? req.birthdays[0] : "1990-01-01")],
  seat_numbers: seatNumber ? [Number(seatNumber)] : [],
  return_seat_numbers: [],
  data: JSON.stringify(dataArray)
};

return [{
  json: {
    session_id: Number(user.id || req.session_id || 0),
    phone_number: phone,
    order,
    original_req: req,
    seat_number: seatNumber
  }
}];

const source = $json;
const request = $('Build Order Payload').first().json;

const orderId = source.id ?? source.order_id;
const paymentLink = source.payment_link ?? source.payment_url;
const ticketUrl = source.ticket_url ?? source.order_url ?? source.public_order_url ?? null;

if (!orderId || !paymentLink) {
  throw new Error('Backend não retornou order_id e payment_link');
}

return [{
  json: {
    ...request,
    order_id: String(orderId),
    payment_link: String(paymentLink),
    ticket_url: ticketUrl,
    seat_number: request.seat_number
  }
}];

const root = $json.body ?? $json;
const data = root.data ?? {};
const key = data.key ?? {};
// Na Evolution, root.sender costuma ser o número da instância.
// O cliente real vem em data.key.remoteJid quando fromMe=false.
const sender = key.remoteJid ?? root.sender ?? '';
const phone = String(sender).split('@')[0].replace(/\D/g, '');
const eventId = String(key.id ?? root.event_id ?? '');
const messageType = data.messageType ?? 'conversation';
const message = data.message?.conversation ?? data.message?.extendedTextMessage?.text ?? data.text ?? '';
if (String(sender).includes('@g.us')) return [];
if (!phone || !eventId || key.fromMe === true) return [];
return [{ json: { event_id: eventId, phone_number: phone, full_name: String(data.pushName ?? 'Cliente').slice(0, 200), message: String(message).trim().slice(0, 4000), message_type: messageType, raw_payload: root } }];

